# ============================================================
#  HUNNIDS - Terminos + Privacidad (encoding-safe, UTF-8 exacto)
#  Ejecutalo DENTRO de la carpeta del repo (vercel-app-page).
#  Uso:  powershell -ExecutionPolicy Bypass -File agregar-legales-v2.ps1
# ============================================================
$ErrorActionPreference = "Stop"
if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: No encuentro package.json. Move el script a la carpeta del repo." -ForegroundColor Red
    exit 1
}
function Write-B64($path, $b64) {
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), $bytes)
    Write-Host ("  OK  " + $path) -ForegroundColor Green
}
Write-Host "Escribiendo archivos (UTF-8 exacto)..." -ForegroundColor Cyan
Write-B64 "src/app/terminos/page.tsx" ""
Write-B64 "src/app/privacidad/page.tsx" ""
Write-B64 "src/components/layout/Footer.tsx" ""
Write-B64 "src/app/sitemap.ts" ""

Write-Host ""
Write-Host "Listo. Ahora redeploya para actualizar la web:" -ForegroundColor Green
Write-Host "   vercel --prod"